<?php
namespace App\Http\Controllers;
use Carbon\Carbon;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class RosterRotationController extends Controller {
 public function create(){return view('roster.rotation.create',['people'=>DB::table('tblRosterPerson')->where('Status',1)->whereIn('WorkMode',['Roster','Both'])->orderBy('PersonName')->get(),'locations'=>DB::table('tblRosterLocation')->where('Status',1)->orderBy('LocationName')->get(),'devices'=>DB::table('tblDevice')->where('Status',1)->orderBy('DeviceName')->get()]);}
 public function store(Request $r){$d=$r->validate(['TypeName'=>'required|max:80','StartDate'=>'required|date','EndDate'=>'required|date|after_or_equal:StartDate','RotationDays'=>'required|integer|min:1|max:31','RosterLocationID'=>'required|exists:tblRosterLocation,RosterLocationID','DeviceID'=>'required|exists:tblDevice,DeviceID','Start'=>['required','array','min:1','max:6'],'End'=>['required','array'],'Guard'=>['required','array']]);$n=count($d['Start']);if(count($d['End'])!==$n||count($d['Guard'])!==$n)return back()->withInput()->withErrors(['Start'=>'Every shift requires a start, end, and guard.']);$rows=[];foreach($d['Start'] as $i=>$start){$end=$d['End'][$i]??null;$guard=$d['Guard'][$i]??null;if(!$end||!$guard)return back()->withInput()->withErrors(['Start'=>'Every shift requires a start, end, and guard.']);$rows[]=['start'=>$start,'end'=>$end,'guard'=>$guard];}$this->validateCoverage($rows);$settings=DB::table('tblRosterSetting')->where('id',1)->first();$shiftIds=[];foreach($rows as $i=>$row){DB::table('tblRosterShift')->updateOrInsert(['ShiftName'=>$d['TypeName'].' Shift '.($i+1)],['StartTime'=>$row['start'],'EndTime'=>$row['end'],'CrossesMidnight'=>$row['end']<=$row['start'],'EntryEarlyMinutes'=>$settings->EntryEarlyMinutes,'EntryLateMinutes'=>$settings->EntryLateMinutes,'ExitEarlyMinutes'=>$settings->ExitEarlyMinutes,'ExitLateMinutes'=>$settings->ExitLateMinutes,'RequiredPeople'=>1,'Status'=>1,'updated_at'=>now(),'created_at'=>now()]);$shiftIds[]=DB::table('tblRosterShift')->where('ShiftName',$d['TypeName'].' Shift '.($i+1))->value('RosterShiftID');}$days=Carbon::parse($d['StartDate'])->diffInDays(Carbon::parse($d['EndDate']));$insert=[];for($offset=0;$offset<=$days;$offset++){ $date=Carbon::parse($d['StartDate'])->addDays($offset)->toDateString();$rotate=intdiv($offset,$d['RotationDays'])%$n;foreach($rows as $i=>$row){$guard=$rows[($i+$rotate)%$n]['guard'];$insert[]=['RosterDate'=>$date,'RosterPersonID'=>$guard,'ProxyPersonID'=>null,'RosterShiftID'=>$shiftIds[$i],'RosterLocationID'=>$d['RosterLocationID'],'DeviceID'=>$d['DeviceID'],'AssignmentType'=>'Security Rotation','StartTime'=>$row['start'],'EndTime'=>$row['end'],'CrossesMidnight'=>$row['end']<=$row['start'],'EntryEarlyMinutes'=>$settings->EntryEarlyMinutes,'EntryLateMinutes'=>$settings->EntryLateMinutes,'ExitEarlyMinutes'=>$settings->ExitEarlyMinutes,'ExitLateMinutes'=>$settings->ExitLateMinutes,'Status'=>'Active','Remarks'=>'Generated rotation: '.$d['TypeName'],'created_at'=>now(),'updated_at'=>now()];}}DB::table('tblRosterAssignment')->insert($insert);return redirect()->route('roster.assignments.index',['month'=>Carbon::parse($d['StartDate'])->format('Y-m')])->with('success',count($insert).' rotation duties generated.');}
 private function validateCoverage($rows){$rows=collect($rows)->sortBy('start')->values();$first=(int)substr($rows[0]['start'],0,2)*60+(int)substr($rows[0]['start'],3,2);foreach($rows as $i=>$r){$s=(int)substr($r['start'],0,2)*60+(int)substr($r['start'],3,2);$e=(int)substr($r['end'],0,2)*60+(int)substr($r['end'],3,2);if($e<=$s)$e+=1440;$next=$i==count($rows)-1?$first+1440:(int)substr($rows[$i+1]['start'],0,2)*60+(int)substr($rows[$i+1]['start'],3,2);if($e!==$next)abort(422,'Shift times must cover exactly 24 hours with no gap or overlap.');}}
}
